The script below reads a JSON file, supports a top-level list of records, a single object, or simple JSON Lines fallback, flattens nested dictionaries using dot notation such as `address.city`, and writes a well-formed CSV. It preserves header order by first appearance, leaves missing/null values blank, and serializes lists or other complex values as JSON strings so they remain valid CSV cell contents.

```python
#!/usr/bin/env python3

import sys
import json
import csv
from collections.abc import Mapping


def load_json_records(path):
    """
    Load records from a JSON file.

    Supports:
    - A top-level JSON array of objects
    - A single top-level JSON object
    - A JSON object containing a list value, e.g. {"users": [...]}
    - Fallback JSON Lines parsing, skipping malformed blank/bad lines
    """
    with open(path, "r", encoding="utf-8-sig") as f:
        text = f.read()

    if not text.strip():
        return []

    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        records = []
        bad_lines = 0

        for line_no, line in enumerate(text.splitlines(), start=1):
            line = line.strip()
            if not line:
                continue

            try:
                records.append(json.loads(line))
            except json.JSONDecodeError:
                bad_lines += 1
                print(
                    f"Warning: skipping malformed JSON line {line_no}",
                    file=sys.stderr,
                )

        if not records and bad_lines:
            raise ValueError("Input is not valid JSON and no valid JSON Lines were found")

        return records

    if isinstance(data, list):
        return data

    if isinstance(data, dict):
        # If the object wraps a list of records, use the first list value found.
        for value in data.values():
            if isinstance(value, list):
                return value

        # Otherwise treat the object itself as one record.
        return [data]

    # Scalar top-level JSON value.
    return [{"value": data}]


def stringify_value(value):
    """
    Convert Python/JSON values to CSV-safe scalar values.

    csv.writer handles quoting/escaping. This function only decides the textual
    representation of non-string values.
    """
    if value is None:
        return ""

    if isinstance(value, bool):
        return "true" if value else "false"

    if isinstance(value, (int, float)):
        return str(value)

    if isinstance(value, str):
        return value

    # Lists or unexpected nested structures are preserved as compact JSON.
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def flatten_record(obj, prefix="", out=None):
    """
    Flatten nested dictionaries using dot notation.

    Example:
      {"name": "Alice", "address": {"city": "NYC"}}
    becomes:
      {"name": "Alice", "address.city": "NYC"}

    Lists are kept as JSON strings rather than expanded, since expanding arrays
    can create ambiguous CSV shapes.
    """
    if out is None:
        out = {}

    if isinstance(obj, Mapping):
        if not obj and prefix:
            out[prefix] = ""

        for key, value in obj.items():
            key = str(key)
            full_key = f"{prefix}.{key}" if prefix else key

            if isinstance(value, Mapping):
                flatten_record(value, full_key, out)
            else:
                out[full_key] = stringify_value(value)
    else:
        out[prefix or "value"] = stringify_value(obj)

    return out


def write_csv(records, output_path):
    flattened_rows = []
    headers = []
    seen_headers = set()

    for record in records:
        flat = flatten_record(record)
        flattened_rows.append(flat)

        for key in flat.keys():
            if key not in seen_headers:
                seen_headers.add(key)
                headers.append(key)

    with open(output_path, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(
            f,
            fieldnames=headers,
            extrasaction="ignore",
            lineterminator="\n",
        )

        if headers:
            writer.writeheader()
            for row in flattened_rows:
                writer.writerow({header: row.get(header, "") for header in headers})


def main():
    if len(sys.argv) != 3:
        print(
            f"Usage: {sys.argv[0]} SOURCE_JSON_PATH OUTPUT_CSV_PATH",
            file=sys.stderr,
        )
        sys.exit(2)

    source_path = sys.argv[1]
    output_path = sys.argv[2]

    try:
        records = load_json_records(source_path)
        write_csv(records, output_path)
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
